#include <iostream>
#include <string>
using namespace std;

int find_substring_in_string(const string& s, const string& pattern, int start_idx) {
    for (int i = start_idx; i <= (int)s.size() - (int)pattern.size(); ++i) {
        if (s[i] == pattern[0]) {
            bool match_found = true;
            for (int j = 1; j < (int)pattern.size(); ++j) {
                if (s[i + j] != pattern[j]) {
                    match_found = false;
                    break;
                }
            }
            if (match_found) return i;
        }
    }
    return -1;
}

int main() {
    string input_str, temp_str, output_str;
    cin >> input_str;
    int at_index = find_substring_in_string(input_str, "at", 1);
    temp_str = input_str.substr(0, at_index) + '@' + input_str.substr(at_index + 2);
    int dot_index = find_substring_in_string(temp_str, "dot", 1);
    int start_pos = 0;
    while (dot_index != -1 && dot_index < (int)temp_str.size() - 3) {
        output_str += temp_str.substr(start_pos, dot_index - start_pos) + ".";
        start_pos = dot_index + 3;
        dot_index = find_substring_in_string(temp_str, "dot", start_pos);
    }
    output_str += temp_str.substr(start_pos);
    cout << output_str;
    return 0;
}
